<?php
declare(strict_types=1);use PHPUnit\Framework\TestCase;
final class ProductionPermitPersistenceObservationEvidenceContractTest extends TestCase{public function testObservationReadsClearStaleDbError():void{$s=(string)file_get_contents(__DIR__.'/../../includes/POD/ProductionPermitPersistenceObservationRepository.php');self::assertGreaterThanOrEqual(3,substr_count($s,"\$wpdb->last_error=''"));self::assertStringContainsString("'query_state'=>'UNAVAILABLE'",$s);self::assertStringContainsString("'retry_permitted'=>false",$s);self::assertStringContainsString("'external_execution_authorized'=>false",$s);}}